CREATE TABLE tblMemberAccount9 (id VARCHAR(40) PRIMARY KEY, username VARCHAR(60) UNIQUE NOT NULL, salt VARCHAR(64) NOT NULL, credential VARCHAR(128) NOT NULL, role VARCHAR(16) NOT NULL);
CREATE TABLE tblSupplier9 (id VARCHAR(40) PRIMARY KEY, name VARCHAR(150) NOT NULL, address VARCHAR(255) NOT NULL, phone VARCHAR(20) NOT NULL UNIQUE, email VARCHAR(150));
CREATE TABLE tblSparePartCategory9 (id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE tblServiceCategory9 (id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE tblService9 (id VARCHAR(40) PRIMARY KEY,name VARCHAR(150) NOT NULL,description VARCHAR(500) NOT NULL,categoryId VARCHAR(40) NOT NULL,listedPrice BIGINT NOT NULL,estimatedDuration INTEGER NOT NULL,FOREIGN KEY(categoryId) REFERENCES tblServiceCategory9(id));
CREATE TABLE tblSparePart9 (id VARCHAR(40) PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,description VARCHAR(500) NOT NULL,categoryId VARCHAR(40) NOT NULL,sellingPrice BIGINT NOT NULL,unit VARCHAR(30) NOT NULL,FOREIGN KEY(categoryId) REFERENCES tblSparePartCategory9(id));
CREATE TABLE tblPurchaseInvoice9 (id VARCHAR(40) PRIMARY KEY,supplierId VARCHAR(40) NOT NULL,createdById VARCHAR(40) NOT NULL,confirmedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,paymentStatus VARCHAR(12) NOT NULL DEFAULT 'UNPAID',paymentMethod VARCHAR(30),paidAt DATETIME,FOREIGN KEY(supplierId) REFERENCES tblSupplier9(id), FOREIGN KEY(createdById) REFERENCES tblMemberAccount9(id));
CREATE TABLE tblPurchaseInvoiceDetail9 (purchaseInvoiceId VARCHAR(40) NOT NULL,partId VARCHAR(40) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unitPrice BIGINT NOT NULL CHECK(unitPrice>0),PRIMARY KEY(purchaseInvoiceId,partId),FOREIGN KEY(purchaseInvoiceId) REFERENCES tblPurchaseInvoice9(id),FOREIGN KEY(partId) REFERENCES tblSparePart9(id));
CREATE TABLE tblStockIssue9 (id VARCHAR(40) PRIMARY KEY,partId VARCHAR(40) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),FOREIGN KEY(partId) REFERENCES tblSparePart9(id));
CREATE VIEW v_stock_balance AS SELECT p.id,COALESCE((SELECT SUM(d.quantity) FROM tblPurchaseInvoiceDetail9 d WHERE d.partId=p.id),0)-COALESCE((SELECT SUM(s.quantity) FROM tblStockIssue9 s WHERE s.partId=p.id),0) AS stockQuantity FROM tblSparePart9 p;
